import{z as i,x as o,o as t,c as d,q as B,j as r,D as l,d as e,s as n,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"对齐税的测量","description":"","frontmatter":{"title":"对齐税的测量","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aeval-alignment-tax.md","filePath":"llm/aeval-alignment-tax.md","lastUpdated":1791413859000}'),m={name:"llm/aeval-alignment-tax.md"};function p(D,a,F,h,T,C){const A=o("Mermaid");return t(),d("div",null,[a[2]||(a[2]=B('<h1 id="对齐税的测量" tabindex="-1">对齐税的测量 <a class="header-anchor" href="#对齐税的测量" aria-label="Permalink to &quot;对齐税的测量&quot;">​</a></h1><div class="epigraph"><p>安全不是免费的，但「税」要先证明因果：对齐前后各跑一遍能力榜，量到的只是混着换数据、换步数、换提示的总账，不是税。</p><footer>—— Bai et al., 2022 与 Askell et al., 2021 都报告了有用/无害的权衡口径</footer></div><p><a href="/llm/aeval-multiturn-safety">上一课</a>把安全评测从单轮扩到会话路径与首违轮。安全工作点每收紧一格，产品侧都会问同一句：模型变笨了吗？本课把这句质问变成测量：对齐税的定义、配对与归因。第一课的三元组 \\(S(\\theta,P,J)\\) 在这里再入口：冻结 \\(P\\) 与 \\(J\\)，看 \\(\\theta\\) 的哪一部分改动交了多少能力。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「对齐后数学掉两分」不是对齐税。从基座到发布，中间可能同时变了预训练数据配比、训练步数、检查点选择、系统提示、解码配置；能力评测自己有方差（口径见<a href="/llm/eval-variance-seed">评测方差与种子</a>），两分的差常常只是采样噪音。更隐蔽的是协议混入：输出变长后撞上截断、格式偏好变了导致抽取失败——评测协议吃掉的分数被记在安全头上。缺口是把「安全干预的因果贡献」从总变化里隔离出来，并且分域报告：税不是均匀的，均匀假设会让免税的域替交税的域背书。</p><p><span class="marginnote">「消融实验」借自生物学：切掉一部分，看整体少了什么功能，就知道那部分负责什么。对齐税测量里的消融就是只动安全相关的那一处、其余全部冻结，重测一次——前后的差才能记在安全头上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="三层配对" tabindex="-1">三层配对 <a class="header-anchor" href="#三层配对" aria-label="Permalink to &quot;三层配对&quot;">​</a></h3><p><strong>权重层</strong>：同一基座，只加安全数据或偏好训练的消融检查点对，同 harness、同解码跑能力套件，逐域差分 \\(\\Delta_c = S_{\\text{aligned}}(c) - S_{\\text{base}}(c)\\)。<strong>提示层</strong>：同一权重，加/不加安全系统提示各测一遍——提示税常比权重税大，而且免费可调。<strong>门层</strong>：输入/输出过滤器的误杀已在<a href="/llm/aeval-overrefusal-metric">越权度量</a>计入行为侧，这里补延迟与吞吐的税。三层各自单独消融，才有 \\(\\Delta_c = \\Delta^{\\text{数据}}_c + \\Delta^{\\text{提示}}_c + \\Delta^{\\text{门}}_c + \\epsilon_c\\) 的可加分解；一次只测首尾两点，因子混在一起，归因无从谈起。</p>',9)),(t(),r(s,null,{default:l(()=>[n(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E5%90%8C%E4%B8%80%E5%9F%BA%E5%BA%A7%22%5D%20--%3E%20ABL%5B%22%E5%AE%89%E5%85%A8%E6%B6%88%E8%9E%8D%E6%A3%80%E6%9F%A5%E7%82%B9%E5%AF%B9%22%5D%0A%20%20ABL%20--%3E%20SUITE%5B%22%E5%90%8C%20harness%20%E8%83%BD%E5%8A%9B%E5%A5%97%E4%BB%B6%22%5D%0A%20%20SUITE%20--%3E%20DOM%5B%22%E5%88%86%E5%9F%9F%E5%B7%AE%E5%88%86%22%5D%0A%20%20DOM%20--%3E%20PROMPT%5B%22%E6%8F%90%E7%A4%BA%E5%B1%82%E9%85%8D%E5%AF%B9%EF%BC%9A%E5%8A%A0%20%2F%20%E4%B8%8D%E5%8A%A0%E5%AE%89%E5%85%A8%E6%8F%90%E7%A4%BA%22%5D%0A%20%20PROMPT%20--%3E%20GATE%5B%22%E9%97%A8%E5%B1%82%EF%BC%9A%E5%BB%B6%E8%BF%9F%E4%B8%8E%E8%AF%AF%E6%8B%A6%E6%88%90%E6%9C%AC%22%5D%0A%20%20GATE%20--%3E%20PROF%5B%22%E7%A8%8E%E5%89%96%E9%9D%A2%E6%8A%A5%E5%91%8A%EF%BC%9A%E5%8C%BA%E9%97%B4%20%2B%20%E5%88%86%E5%9F%9F%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("税为什么集中：安全监督偏短、偏模板、偏拒答与说教，它把输出长度与风格分布整体推移；能力评测若奖励长而全的作答，风格移动会被读成能力下降，反之亦然——所以税必须与判分表的风格敏感性一起解读。拒答与谨慎泛化到共享特征的机制，正是第一课引入、"),E("a",{href:"/llm/over-refusal"},"过度拒绝"),e("机制课展开的那条捷径，能力侧的税与安全侧的越权是同一枚硬币。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"提示税的直觉：安全系统提示像给每个员工发了本《行为守则》，无论当天任务多简单都得随身带着——写代码的请求也会被「请谨慎作答」的措辞带得啰嗦起来。它不用重训就能调，所以先量提示层的税，常常是性价比最高的一步。")],-1)),a[6]||(a[6]=E("p",null,"「对齐后数学掉两分」里可能混着的东西，与消融如何把它们剥开：",-1)),(t(),r(s,null,{default:l(()=>[n(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20TOTAL%5B%22%E6%A6%9C%E5%8D%95%E5%B7%AE%E5%80%BC%EF%BC%9A%E6%95%B0%E5%AD%A6%20-2%20%E5%88%86%22%5D%20--%3E%20C1%5B%22%E9%A2%84%E8%AE%AD%E7%BB%83%E6%95%B0%E6%8D%AE%E5%8F%98%E4%BA%86%EF%BC%9F%22%5D%0A%20%20TOTAL%20--%3E%20C2%5B%22%E8%AE%AD%E7%BB%83%E6%AD%A5%E6%95%B0%20%2F%20%E6%A3%80%E6%9F%A5%E7%82%B9%E5%8F%98%E4%BA%86%EF%BC%9F%22%5D%0A%20%20TOTAL%20--%3E%20C3%5B%22%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%E5%8F%98%E4%BA%86%EF%BC%9F%22%5D%0A%20%20TOTAL%20--%3E%20C4%5B%22%E5%8D%8F%E8%AE%AE%EF%BC%9A%E6%88%AA%E6%96%AD%20%2F%20%E6%8A%BD%E5%8F%96%E5%A4%B1%E8%B4%A5%EF%BC%9F%22%5D%0A%20%20TOTAL%20--%3E%20C5%5B%22%E9%87%87%E6%A0%B7%E5%99%AA%E9%9F%B3%20%C2%B11%20%E5%88%86%22%5D%0A%20%20ABL%5B%22%E6%B6%88%E8%9E%8D%EF%BC%9A%E5%8F%AA%E5%8A%A8%E5%AE%89%E5%85%A8%E6%95%B0%E6%8D%AE%EF%BC%8C%E5%85%B6%E4%BD%99%E5%85%A8%E5%86%BB%E7%BB%93%22%5D%20--%3E%20TAX%5B%22%E5%B7%AE%E5%80%BC%E6%89%8D%E6%98%AF%E7%A8%8E%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=B('<p>提示税为什么反而大：权重改动可以局部，系统提示影响全分布——每一条请求都背着它。<span class="marginnote">Bai et al. 2022 的原始口径就点破了比较对象：有用与无害在数据上互相挤压，税的大小取决于你在帕累托上比的是哪两点；不指定工作点的「对齐税」没有操作定义，扫一遍工作点各报一数，才是可辩护的口径。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>税可为负：对齐同时提升指令跟随与格式稳定，有的域分数是涨的，剖面必须完整公布，挑着报就是用测量做宣传。能力评测与安全评测共用同一解码配置，否则又是第一课警告过的两套不可比数字。多次采样取区间，不报单次贪心；报告绑定检查点谱系，让下一任能复现这套消融。最后，不要用单一总分宣布「对齐让模型变笨」——总分里交税的域与涨分的域互相抵消，抵消后的数字不归因于任何人。</p><p><span class="marginnote">初学者容易拿一个总分说「对齐让模型变笨了」。实际上税的剖面是有域掉分、也有域涨分（比如指令跟随、格式稳定往往变好），总分一平均互相抵消，剩下的数既不属于交税的域，也不属于涨分的域——结论必须落在分域剖面上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对齐税是安全干预的因果贡献，不是对齐前后能力榜的差值。</li><li>三层配对消融：权重、提示、门；只有分层才能分解，只测首尾只能吵架。</li><li>分域剖面是主表：税集中在创意写作、长文与敏感域，数学代码基本免税。</li><li>与判分表的风格敏感性一起解读：长度与文风移动会伪装成能力变化。</li><li>工作点指定在先：帕累托上不指明比哪两点，税就没有定义。</li><li>出处：Bai et al., 2022；Askell et al., 2021；本课程的消融口径整理。</li></ul>',6))])}const _=i(m,[["render",p]]);export{f as __pageData,_ as default};
